# ────────────────────────────────────────────────────────────────────────
# # Прогнозирование волатильности USD/RUB и EUR/RUB: GARCH(1,1) и GARCH–XGBoost
# 
# Данные — опубликованные Банком России курсы на фактические даты наблюдений за 2014–2025 годы. Выполняйте ячейки последовательно сверху вниз. Для воспроизводимости используйте локальные файлы `XML_dynamic.xml` и `XML_dynamic_EUR.xml`, а также Python-окружение с пакетами `pandas`, `numpy`, `matplotlib`, `arch`, `xgboost`, `scikit-learn`.
# 
# **Смысл прогноза.** Наблюдаемая дневная доходность — $r_t=\ln(P_t/P_{t-1})$. Для сравнения моделей используется прокси реализованной **дисперсии** $r_t^2$. GARCH выдаёт прогноз условной дисперсии $h_t$. XGBoost прогнозирует ошибку этого прогноза $e_t=r_t^2-h_t$. Гибридный прогноз равен $\max(0,h_t+\hat e_t)$. Все слагаемые имеют одинаковую размерность; квадрат доходности не является истинной наблюдаемой условной дисперсией.
# 
# Для запуска в этом проекте выберите ядро `Python (vak)` из `.venv`. В новом окружении установите зависимости командой `python -m pip install pandas numpy matplotlib arch xgboost scikit-learn ipykernel nbclient`.

# ────────────────────────────────────────────────────────────────────────
# ## 1. Импорт библиотек

# ────────────────────────────────────────────────────────────────────────
# %%  [2]

from pathlib import Path
import xml.etree.ElementTree as ET

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from arch import arch_model
from sklearn.metrics import mean_absolute_error, mean_squared_error
from xgboost import XGBRegressor

DATA_DIR = Path.cwd()
RESULTS_DIR = DATA_DIR / 'results'
RESULTS_DIR.mkdir(exist_ok=True)
RANDOM_STATE = 42
GARCH_REFIT_EVERY = 40
XGB_REFIT_EVERY = 20
GARCH_MIN_HISTORY = 252
ROLLING_WINDOW = 10
plt.rcParams.update({'figure.figsize': (12, 4.5), 'font.size': 11, 'axes.grid': True})
print('Рабочая папка:', DATA_DIR)

# ────────────────────────────────────────────────────────────────────────
# ## 2. Загрузка и обработка данных

# ────────────────────────────────────────────────────────────────────────
# %%  [3]

def load_cbr_xml(path, expected_code):
        # ElementTree читает кодировку windows-1251 из XML-декларации.
        root = ET.parse(path).getroot()
        assert root.tag == 'ValCurs' and root.attrib.get('ID') == expected_code
        rows = []
        for record in root.findall('Record'):
            nominal = float(record.findtext('Nominal').replace(',', '.'))
            value = float(record.findtext('Value').replace(',', '.'))
            assert nominal > 0
            rows.append((record.attrib['Date'], value / nominal))
        df = pd.DataFrame(rows, columns=['date', 'rate'])
        df['date'] = pd.to_datetime(df['date'], format='%d.%m.%Y', errors='raise')
        df = df.sort_values('date').set_index('date')
        df.index.name = 'date'
        assert len(df) > 0 and not df.index.has_duplicates
        assert df.index.is_monotonic_increasing
        assert np.isfinite(df['rate']).all() and (df['rate'] > 0).all()
        return df


def describe_rates(df, currency_name):
        print(f'\n{currency_name}: первые наблюдения')
        print(df.head())
        print('Последние наблюдения:')
        print(df.tail())
        print('Число наблюдений:', len(df))
        print('Диапазон дат:', df.index.min().date(), '—', df.index.max().date())
        print('Типы данных:', df.dtypes.to_dict(), '| date:', df.index.dtype)
        print('NaN:', df.isna().sum().to_dict())
        print('Дубликаты дат:', df.index.duplicated().sum())
        print('Минимальный и максимальный курс:', df['rate'].min(), df['rate'].max())


usd_rates = load_cbr_xml(DATA_DIR / 'XML_dynamic.xml', 'R01235')
describe_rates(usd_rates, 'USD/RUB')

# ────────────────────────────────────────────────────────────────────────
# ## 3. Анализ исходных данных
# 
# Временной индекс сохраняет только опубликованные даты ЦБ РФ. Выходные и праздники искусственно не добавляются: «следующий день» в эксперименте означает следующее доступное наблюдение.

# ────────────────────────────────────────────────────────────────────────
# %%  [4]

fig, ax = plt.subplots()
usd_rates['rate'].plot(ax=ax, color='#245b87', linewidth=1)
ax.set(title='Официальный курс USD/RUB, 2014–2025', xlabel='Дата', ylabel='RUB за 1 USD')
fig.tight_layout()
plt.show()

# ────────────────────────────────────────────────────────────────────────
# ## 4. Расчёт логарифмических доходностей

# ────────────────────────────────────────────────────────────────────────
# %%  [5]

def make_returns(rates):
        result = rates.copy()
        result['return'] = np.log(result['rate'] / result['rate'].shift(1))
        result = result.dropna(subset=['return'])
        assert result.index.is_monotonic_increasing and not result.index.has_duplicates
        assert np.isfinite(result['return']).all()
        return result


usd_data = make_returns(usd_rates)
print('Количество доходностей:', len(usd_data))
print(usd_data['return'].agg(['mean', 'std', 'min', 'max']))

fig, ax = plt.subplots()
usd_data['return'].plot(ax=ax, color='#245b87', linewidth=0.8)
ax.set(title='Логарифмические доходности USD/RUB, 2014–2025', xlabel='Дата', ylabel='Логарифмическая доходность')
fig.tight_layout()
fig.savefig(RESULTS_DIR / 'usd_returns.png', dpi=250)
plt.show()

# ────────────────────────────────────────────────────────────────────────
# ## 5. Разделение train/test

# ────────────────────────────────────────────────────────────────────────
# %%  [6]

split_usd = int(len(usd_data) * 0.8)
usd_train = usd_data.iloc[:split_usd]
usd_test = usd_data.iloc[split_usd:]
assert usd_train.index.max() < usd_test.index.min()
print('Train:', len(usd_train), usd_train.index.min().date(), '—', usd_train.index.max().date())
print('Test: ', len(usd_test), usd_test.index.min().date(), '—', usd_test.index.max().date())

# ────────────────────────────────────────────────────────────────────────
# ## 6. Базовая модель GARCH(1,1)
# 
# Оценивается GARCH(1,1) с нулевым условным средним и нормальными инновациями. Доходности умножаются на 100 и измеряются в процентных пунктах. Поэтому $h_t$ и остаточная ошибка XGBoost выражены в процентных пунктах **в квадрате**. Для итоговых CSV и метрик прогнозы делятся на $100^2=10\,000$ и сравниваются с исходным $r_t^2$.

# ────────────────────────────────────────────────────────────────────────
# %%  [7]

def fit_garch(history_pct):
        model = arch_model(history_pct, mean='Zero', vol='GARCH', p=1, q=1,
                           dist='normal', rescale=False)
        fit = model.fit(disp='off', show_warning=False, options={'maxiter': 1000})
        assert fit.convergence_flag == 0, f'GARCH не сошёлся: код {fit.convergence_flag}'
        assert fit.conditional_volatility.index.equals(history_pct.index)
        assert fit.resid.index.equals(history_pct.index)
        assert len(fit.conditional_volatility) == len(history_pct)
        assert np.isfinite(fit.conditional_volatility).all()
        assert np.isfinite(fit.resid).all()
        return fit


usd_initial_fit = fit_garch(usd_train['return'] * 100)
print('Параметры GARCH на train (%²):')
print(usd_initial_fit.params)
print('Сходимость: код', usd_initial_fit.convergence_flag)
print('Условная волатильность (%, последние 5):')
print(usd_initial_fit.conditional_volatility.tail())
print('Условная дисперсия (%², последние 5):')
print(usd_initial_fit.conditional_volatility.pow(2).tail())
print('Остатки (%, последние 5):')
print(usd_initial_fit.resid.tail())

# ────────────────────────────────────────────────────────────────────────
# ## 7. Формирование признаков XGBoost
# 
# Признаки для даты $t$: пять лагов доходности $r_{t-1},\ldots,r_{t-5}$, выборочное стандартное отклонение **10 предыдущих** доходностей и доступный перед датой $t$ прогноз GARCH $h_t$. Окно 10 наблюдений сглаживает однодневные выбросы, оставаясь локальным. Все доходности для признаков берутся через `shift`; текущее $r_t$ в признаки не входит.

# ────────────────────────────────────────────────────────────────────────
# %%  [8]

FEATURE_COLUMNS = [f'lag_{i}' for i in range(1, 6)] + ['rolling_std_10', 'garch_variance']


def make_past_features(returns_pct):
        features = pd.DataFrame(index=returns_pct.index)
        for lag in range(1, 6):
            features[f'lag_{lag}'] = returns_pct.shift(lag)
        features['rolling_std_10'] = returns_pct.shift(1).rolling(ROLLING_WINDOW).std()
        features['garch_variance'] = np.nan  # заполняется последовательным прогнозом
        assert features['lag_1'].iloc[1:].equals(returns_pct.shift(1).iloc[1:])
        assert features['rolling_std_10'].iloc[:ROLLING_WINDOW].isna().all()
        return features


usd_features_example = make_past_features(usd_data['return'] * 100)
print('Признаки XGBoost:', FEATURE_COLUMNS)
print(usd_features_example.iloc[10:15].drop(columns='garch_variance'))
print('Прогноз GARCH заполняется последовательно в walk_forward().')

# ────────────────────────────────────────────────────────────────────────
# ## 8. Гибридная модель GARCH–XGBoost
# 
# В обучающей части также получаются последовательные **прогнозы на один шаг вперёд**: для каждой даты GARCH опирается только на более ранние доходности. Цель XGBoost — $e_t=(100r_t)^2-h_t$ в единицах %². Это ошибка прогноза **дисперсии**, а не обычный остаток доходности. Итог $\max(0,h_t+\hat e_t)$ ограничен снизу нулём, поскольку отрицательная дисперсия невозможна. Гиперпараметры XGBoost заданы заранее, без подбора по тесту.

# ────────────────────────────────────────────────────────────────────────
# %%  [9]

XGB_PARAMS = {
    'n_estimators': 200,
    'max_depth': 4,
    'learning_rate': 0.05,
    'objective': 'reg:squarederror',
    'tree_method': 'hist',
    'random_state': RANDOM_STATE,
    'n_jobs': 1,
    'verbosity': 0,
}
print('Гиперпараметры XGBoost:', XGB_PARAMS)

# ────────────────────────────────────────────────────────────────────────
# ## 9. Walk-forward validation
# 
# Первые 252 доходности служат стартовой историей для GARCH. На каждой следующей дате строится прогноз на одно наблюдение вперёд. Параметры GARCH заново оцениваются каждые 40 наблюдений; между переоценками его условная дисперсия обновляется точной рекурсией GARCH(1,1) после появления фактической доходности. На границе 80/20 GARCH переоценивается на полном train. XGBoost впервые обучается только на последовательных ошибках GARCH внутри train, затем обновляется каждые 20 тестовых наблюдений по накопленной истории. Фактическое значение даты $t$ добавляется в историю **после** обоих прогнозов этой даты.

# ────────────────────────────────────────────────────────────────────────
# %%  [10]

def walk_forward(data, currency_name):
    returns_pct = data['return'] * 100
    split = int(len(data) * 0.8)
    assert GARCH_MIN_HISTORY < split < len(data)
    assert data.index[split - 1] < data.index[split]
    features = make_past_features(returns_pct)
    garch_variance = pd.Series(np.nan, index=data.index, dtype=float)
    residual_target = pd.Series(np.nan, index=data.index, dtype=float)
    hybrid_variance = pd.Series(np.nan, index=data.index, dtype=float)
    xgb = None
    next_variance = None
    params_at_split = None
    garch_refits = 0
    xgb_refits = 0

    for t in range(GARCH_MIN_HISTORY, len(data)):
        date = data.index[t]
        # Плановая переоценка и обязательная оценка на всей обучающей части.
        refit = (t == GARCH_MIN_HISTORY or t == split or
                 (t < split and (t - GARCH_MIN_HISTORY) % GARCH_REFIT_EVERY == 0) or
                 (t > split and (t - split) % GARCH_REFIT_EVERY == 0))
        if refit:
            history = returns_pct.iloc[:t]
            assert history.index.max() < date
            fit = fit_garch(history)
            omega = float(fit.params['omega'])
            alpha = float(fit.params['alpha[1]'])
            beta = float(fit.params['beta[1]'])
            last_variance = float(fit.conditional_volatility.iloc[-1] ** 2)
            next_variance = omega + alpha * float(history.iloc[-1] ** 2) + beta * last_variance
            garch_refits += 1
            if t == split:
                params_at_split = fit.params.copy()

        assert next_variance is not None and np.isfinite(next_variance) and next_variance >= 0
        garch_variance.iloc[t] = next_variance
        features.loc[date, 'garch_variance'] = next_variance
        assert np.isfinite(features.loc[date, FEATURE_COLUMNS]).all()

        if t >= split:
            if xgb is None or (t - split) % XGB_REFIT_EVERY == 0:
                known_dates = residual_target.iloc[GARCH_MIN_HISTORY:t].dropna().index
                assert len(known_dates) == t - GARCH_MIN_HISTORY
                assert known_dates.max() < date
                xgb = XGBRegressor(**XGB_PARAMS)
                xgb.fit(features.loc[known_dates, FEATURE_COLUMNS], residual_target.loc[known_dates])
                xgb_refits += 1
            correction = float(xgb.predict(features.loc[[date], FEATURE_COLUMNS])[0])
            hybrid_variance.iloc[t] = max(0.0, next_variance + correction)

        # Обновление состояния разрешено только после получения факта за дату t.
        residual_target.iloc[t] = float(returns_pct.iloc[t] ** 2 - next_variance)
        next_variance = omega + alpha * float(returns_pct.iloc[t] ** 2) + beta * next_variance

    test_dates = data.index[split:]
    predictions = pd.DataFrame({
        'actual': data.loc[test_dates, 'return'].pow(2),
        'garch': garch_variance.loc[test_dates] / 10000,
        'hybrid': hybrid_variance.loc[test_dates] / 10000,
    }, index=test_dates)
    predictions.index.name = 'date'
    assert len(predictions) == len(data) - split
    assert predictions.index.equals(test_dates)
    assert not predictions.isna().any().any()
    assert np.isfinite(predictions.to_numpy()).all()
    assert (predictions >= 0).all().all()
    assert params_at_split is not None
    print(f'{currency_name}: {garch_refits} переоценок GARCH, {xgb_refits} переобучений XGBoost')
    return predictions, params_at_split

# ────────────────────────────────────────────────────────────────────────
# ## 10. Оценка RMSE и MAE
# 
# Обе модели сравниваются с одним и тем же $r_t^2$ на одинаковых тестовых датах. Метрики и CSV выражены в квадрате исходной логарифмической доходности. Числа малы из-за единицы измерения; для визуализации график ниже переводится в %².

# ────────────────────────────────────────────────────────────────────────
# %%  [11]

def evaluate(predictions, currency_name):
        actual = predictions['actual']
        rows = []
        for model_name, column in [('GARCH', 'garch'), ('GARCH-XGBoost', 'hybrid')]:
            forecast = predictions[column]
            assert len(actual) == len(forecast)
            assert actual.index.equals(forecast.index)
            rmse = float(np.sqrt(mean_squared_error(actual, forecast)))
            mae = float(mean_absolute_error(actual, forecast))
            assert np.isclose(rmse, np.sqrt(np.mean((actual - forecast) ** 2)))
            assert np.isclose(mae, np.mean(np.abs(actual - forecast)))
            rows.append({'Currency': currency_name, 'Model': model_name, 'RMSE': rmse, 'MAE': mae})
        return pd.DataFrame(rows)


def run_pipeline(rates, currency_name, file_stub):
        data = make_returns(rates)
        split = int(len(data) * 0.8)
        print(f'\n{currency_name}: {len(rates)} курсов, {len(data)} доходностей; train={split}, test={len(data)-split}')
        print('Train:', data.index[0].date(), '—', data.index[split - 1].date())
        print('Test: ', data.index[split].date(), '—', data.index[-1].date())
        predictions, params = walk_forward(data, currency_name)
        metrics = evaluate(predictions, currency_name)
        predictions.to_csv(RESULTS_DIR / f'{file_stub}_predictions.csv', float_format='%.12g')
        print('GARCH на границе train/test (%²):', params.to_dict())
        print(metrics.to_string(index=False, float_format=lambda x: f'{x:.8g}'))
        return {'data': data, 'predictions': predictions, 'metrics': metrics, 'garch_params': params}


usd_result = run_pipeline(usd_rates, 'USD/RUB', 'usd')

# ────────────────────────────────────────────────────────────────────────
# ## 11. Графики
# 
# На графике тестового интервала все три ряда представлены в %²: умножение на $10\,000$ меняет только шкалу, не результаты метрик.

# ────────────────────────────────────────────────────────────────────────
# %%  [12]

def plot_predictions(result, currency_name, file_stub):
        shown = result['predictions'] * 10000
        fig, ax = plt.subplots(figsize=(13, 5))
        ax.plot(shown.index, shown['actual'], color='#737373', linewidth=0.8,
                alpha=0.75, label='Факт: квадрат доходности')
        ax.plot(shown.index, shown['garch'], color='#245b87', linewidth=1.2,
                label='GARCH(1,1)')
        ax.plot(shown.index, shown['hybrid'], color='#c45724', linewidth=1.2,
                label='GARCH–XGBoost')
        ax.set(title=f'{currency_name}: прогноз дисперсии на тестовом интервале',
               xlabel='Дата', ylabel='Квадрат доходности, %²')
        ax.legend(loc='upper right')
        fig.tight_layout()
        fig.savefig(RESULTS_DIR / f'{file_stub}_comparison.png', dpi=250)
        plt.show()


plot_predictions(usd_result, 'USD/RUB', 'usd')

# ────────────────────────────────────────────────────────────────────────
# ## 12. Итоговые результаты
# 
# Функция `run_pipeline` принимает любой корректно загруженный исторический ряд с колонкой `rate`. EUR/RUB обрабатывается без копирования логики модели. Если локального XML нет, эксперимент USD/RUB остаётся выполнимым.

# ────────────────────────────────────────────────────────────────────────
# %%  [13]

eur_path = DATA_DIR / 'XML_dynamic_EUR.xml'
eur_result = None
if eur_path.exists():
    eur_rates = load_cbr_xml(eur_path, 'R01239')
    describe_rates(eur_rates, 'EUR/RUB')
    eur_result = run_pipeline(eur_rates, 'EUR/RUB', 'eur')
    plot_predictions(eur_result, 'EUR/RUB', 'eur')
else:
    print('Исторический EUR/RUB отсутствует: поместите XML_dynamic_EUR.xml в рабочую папку и запустите эту ячейку повторно.')

metrics_parts = [usd_result['metrics']]
if eur_result is not None:
    metrics_parts.append(eur_result['metrics'])
metrics = pd.concat(metrics_parts, ignore_index=True)
metrics.to_csv(RESULTS_DIR / 'metrics.csv', index=False, float_format='%.12g')
print('\nИтоговая таблица (единицы: квадрат логарифмической доходности):')
print(metrics.to_string(index=False, float_format=lambda x: f'{x:.8g}'))
for name in metrics['Currency'].unique():
    pair = metrics.set_index(['Currency', 'Model']).loc[name]
    print(f"{name}: улучшение RMSE = {pair.loc['GARCH', 'RMSE'] - pair.loc['GARCH-XGBoost', 'RMSE']:.8g}; "
          f"улучшение MAE = {pair.loc['GARCH', 'MAE'] - pair.loc['GARCH-XGBoost', 'MAE']:.8g}")

# ────────────────────────────────────────────────────────────────────────
# ## Описание программной реализации для статьи
# 
#     Вычислительный эксперимент выполнен в Python на исторических значениях официального курса USD/RUB и EUR/RUB Банка России за 2014–2025 годы. Источником служат сохранённые XML-файлы динамики курсов `XML_dynamic.asp`. При чтении учитываются кодировка XML, десятичная запятая и поле `Nominal`: значение курса приводится к одной единице валюты. Записи сортируются по дате; проверяются пропуски, дубликаты и конечность чисел. В ряд не добавляются выходные и праздничные дни, для которых курс не опубликован. Файл однодневного среза валют в моделировании не используется.
# 
# Для каждого валютного ряда рассчитана логарифмическая доходность $r_t=\ln(P_t/P_{t-1})$. Первый пропуск после сдвига удалён. По хронологии 80 % доходностей выделены для обучения и 20 % для тестирования. Перемешивание наблюдений и случайная кросс-валидация не применяются. В качестве доступной по дневному курсу прокси реализованной дисперсии выбран квадрат доходности $r_t^2$. Эта величина шумная: одно дневное наблюдение не позволяет непосредственно измерить скрытую условную дисперсию.
# 
# Базовая модель GARCH(1,1) с нулевым условным средним оценивается библиотекой `arch` на доходностях, умноженных на 100. На каждой дате после стартовой истории из 252 наблюдений вычисляется прогноз условной дисперсии на один следующий опубликованный курс. Параметры модели переоцениваются каждые 40 наблюдений; между переоценками дисперсия обновляется стандартной рекурсией GARCH после получения очередной доходности. На границе обучающей и тестовой выборок параметры оцениваются по всему доступному обучающему периоду. В ячейках выводятся коэффициенты $\omega$, $\alpha_1$, $\beta_1$, условные волатильность и дисперсия, остатки и код сходимости.
# 
# Гибридная модель корректирует прогноз дисперсии GARCH. Целевая переменная XGBoost — разность между квадратом уже наблюдённой доходности и сделанным ранее прогнозом GARCH, оба в единицах %². Признаки состоят из пяти предыдущих доходностей, стандартного отклонения за 10 предыдущих наблюдений и прогноза GARCH на оцениваемую дату. Модель `XGBRegressor` использует 200 деревьев глубины 4, скорость обучения 0,05 и фиксированный `random_state=42`; параметры заданы до тестирования. Обучающие ошибки GARCH формируются последовательно, по прогнозам из информации, доступной до соответствующей даты. XGBoost переобучается через каждые 20 тестовых наблюдений с добавлением только уже раскрытых ошибок. Гибридный прогноз есть сумма прогноза GARCH и поправки XGBoost с отсечением отрицательных значений до нуля.
# 
# Прогнозы обеих моделей и фактический квадрат доходности приведены к исходному масштабу и сопоставлены на одних тестовых датах. Для оценки используются RMSE и MAE. Код проверяет совпадение индексов, длины рядов, отсутствие пропусков и бесконечностей, неотрицательность прогнозов и правильность вычисления метрик. Таблица результатов, дневные прогнозы и рисунки сохраняются в папке `results`. Результаты EUR/RUB вычисляются тем же пайплайном, что и USD/RUB. Сравнение ограничено двумя валютными рядами и дневной прокси $r_t^2$; оно само по себе не доказывает улучшение для иных рынков или мер реализованной волатильности.
